<script setup lang="ts">
import { onMounted, onBeforeUnmount, ref } from 'vue';
import { useVehicleStore } from './stores/vehicle';
import { windowConfig, windowIds } from './config/v8-windows';
import WindowControls from './components/WindowControls.vue';
import DemoTools from './components/DemoTools.vue';
import OperationHistory from './components/OperationHistory.vue';
import VoiceControl from './components/VoiceControl.vue';
import { createV8 } from './scene/v8';
import {staticPreview,modelReviewEnabled} from './config/runtime';
const expanded=ref(false);
const baseline = modelReviewEnabled && new URLSearchParams(location.search).has('baseline');
const store = useVehicleStore(); const viewport = ref<HTMLElement>(); const status = ref('正在准备场景…'); const ready = ref(false);
let scene: ReturnType<typeof createV8> | undefined;
onMounted(() => { try { scene = createV8(viewport.value!, store, (text, loaded) => { status.value=text; ready.value=!!loaded; }); } catch(e) { status.value='无法启动 WebGL：'+String(e); } });
onBeforeUnmount(() => scene?.dispose());
</script><template>
